entries[62552] = { ["name"] = "Fortune Card", ["text"] = "\"You might have better luck with another fortune.\"\nSell Price:" }
entries[62553] = { ["name"] = "Fortune Card", ["text"] = "\"Stay away from mystery meat.\"\nSell Price:" }
entries[62554] = { ["name"] = "Fortune Card", ["text"] = "\"You really should've looted that spider.\"\nSell Price:" }
entries[62555] = { ["name"] = "Fortune Card", ["text"] = "\"Never trust an honest goblin or a sober dwarf.\"\nSell Price:" }
entries[62556] = { ["name"] = "Fortune Card", ["text"] = "\"You'll never know until you loot.\"\nSell Price:" }
entries[62557] = { ["name"] = "Fortune Card", ["text"] = "\"Your future is clouded with a purple rain.\"\nSell Price:" }
entries[62558] = { ["name"] = "Fortune Card", ["text"] = "\"You will hear the tinkling of golden coins.\"\nSell Price:" }
entries[62559] = { ["name"] = "Fortune Card", ["text"] = "\"Trust in the Light, but watch your mount.\"\nSell Price:" }
entries[62560] = { ["name"] = "Fortune Card", ["text"] = "\"Never stand in the shadow of dragons.\"\nSell Price:" }
entries[62561] = { ["name"] = "Fortune Card", ["text"] = "\"The road to Blackrock Mountain is paved with good intentions.\"\nSell Price:" }
entries[62562] = { ["name"] = "Fortune Card", ["text"] = "\"Many raid wipes are in your immediate future.\"\nSell Price:" }
entries[62563] = { ["name"] = "Fortune Card", ["text"] = "\"Epics are like children; none are so wonderful as your own.\"\nSell Price:" }
entries[62564] = { ["name"] = "Fortune Card", ["text"] = "\"Experience, honor points and faction reputation are in the days ahead.\"\nSell Price:" }
entries[62565] = { ["name"] = "Fortune Card", ["text"] = "\"Your greatest fortune is in the friends you have. Especially tanks.\"\nSell Price:" }
entries[62566] = { ["name"] = "Fortune Card", ["text"] = "\"The future looks cataclysmic.\"\nSell Price:" }
entries[62567] = { ["name"] = "Fortune Card", ["text"] = "\"Find beauty in ordinary things. Vendor them for cash.\"\nSell Price:" }
entries[62568] = { ["name"] = "Fortune Card", ["text"] = "\"One who promises to go on a blind date is bound on pickup.\"\nSell Price:" }
entries[62569] = { ["name"] = "Fortune Card", ["text"] = "\"A Shaman's blessing is elementary.\"\nSell Price:" }
entries[62570] = { ["name"] = "Fortune Card", ["text"] = "\"Your outlook looks bright, unless you run into Deathwing.\"\nSell Price:" }
entries[62571] = { ["name"] = "Fortune Card", ["text"] = "\"You have a good chance to roll 100 in the near future.\"\nSell Price:" }
entries[62572] = { ["name"] = "Fortune Card", ["text"] = "\"You will develop a great sense of relaxation (and patience) from the fishing profession.\"\nSell Price:" }
entries[62573] = { ["name"] = "Fortune Card", ["text"] = "\"You will someday be able to afford that mount.\"\nSell Price:" }
entries[62574] = { ["name"] = "Fortune Card", ["text"] = "\"IT IS TIME TO REORDER! For more fortunes, contact F.B. Krazzlestix, Bilgewater Harbor. Bulk discounts available for a small fee.\"\nSell Price:" }
entries[62575] = { ["name"] = "Fortune Card", ["text"] = "\"You have many hidden talents. You will gain more with experience.\"\nSell Price:" }
entries[62576] = { ["name"] = "Fortune Card", ["text"] = "\"He who fights an army is a martyr; he who fights five is elite.\"\nSell Price:" }
entries[62577] = { ["name"] = "Fortune Card", ["text"] = "\"A light heart carries you through bad Battlegrounds.\"\nSell Price:" }
entries[62578] = { ["name"] = "Fortune Card", ["text"] = "\"All of the effort you are making is worth the repair costs.\"\nSell Price:" }
entries[62579] = { ["name"] = "Fortune Card", ["text"] = "\"Never trust a troll. Or a rogue. Especially a troll rogue.\"\nSell Price:" }
entries[62580] = { ["name"] = "Fortune Card", ["text"] = "\"Disbelief destroys the magic.\"\nSell Price:" }
entries[62581] = { ["name"] = "Fortune Card", ["text"] = "\"Now is the time to try something new. Perhaps a new tradeskill.\"\nSell Price:" }
entries[62582] = { ["name"] = "Fortune Card", ["text"] = "\"Every herb blooms in its own sweet time. Then you pick it!\"\nSell Price:" }
entries[62583] = { ["name"] = "Fortune Card", ["text"] = "\"Go take a rest. You deserve it. Remember to rest in an inn though!\"\nSell Price:" }
entries[62584] = { ["name"] = "Fortune Card", ["text"] = "\"He who expects a wipe will never be disappointed.\"\nSell Price:" }
entries[62585] = { ["name"] = "Fortune Card", ["text"] = "\"Never look up when there are flying mounts above you.\"\nSell Price:" }
entries[62586] = { ["name"] = "Fortune Card", ["text"] = "\"You will inherit a large sum of money. You will blow it at the Auction House.\"\nSell Price:" }
entries[62587] = { ["name"] = "Fortune Card", ["text"] = "\"Someone nearby wants to /flirt with you.\"\nSell Price:" }
entries[62588] = { ["name"] = "Fortune Card", ["text"] = "\"Your talents will be recognized and rewarded. Provided your talent spec is good.\"\nSell Price:" }
entries[62589] = { ["name"] = "Fortune Card", ["text"] = "\"Help! I'm being held prisoner in a fortune cookie bakery!\"\nSell Price:" }
entries[62590] = { ["name"] = "Fortune Card", ["text"] = "\"The sun will shine tomorrow.\"\nSell Price:" }
entries[62591] = { ["name"] = "Fortune Card", ["text"] = "\"You will receive a gift from someone you hate.\"\nSell Price:" }
