entries[62599] = { ["name"] = "Fortune Card", ["text"] = "\"You will live a long, happy life with many resurrections along the way.\"\nSell Price:" }
entries[62600] = { ["name"] = "Fortune Card", ["text"] = "\"The path of the faceroller is not the path to wisdom.\"\nSell Price:" }
entries[62601] = { ["name"] = "Fortune Card", ["text"] = "\"All that glitters is not gold. But you can sell it for gold most of the time.\"\nSell Price:" }
entries[62602] = { ["name"] = "Fortune Card", ["text"] = "\"You will give someone a piece of your mind, which you can ill afford.\"\nSell Price:" }
entries[62603] = { ["name"] = "Fortune Card", ["text"] = "\"When life gives you lemons, pay for repair costs.\"\nSell Price:" }
